function companyFrame(root,{assetsBaseUrl,onGuide,onContact}={}){
 if(!assetsBaseUrl)throw new Error('companyFrame requires assetsBaseUrl');
 root.classList.add('ui-company-frame');
 const cleanups=[];
 for(const image of root.querySelectorAll('[data-company-ci]')){
  const variant=image.dataset.companyCi||'inverse';
  const path=companyIdentity.ci[variant];
  const url=new URL(path,new URL(assetsBaseUrl,document.baseURI));
  url.searchParams.set('v',companyCiVersions[path]);
  image.src=url.href;
  image.alt=companyIdentity.name;image.classList.add('ui-company-ci');
 }
 for(const footer of root.querySelectorAll('[data-company-footer]')){
  footer.classList.add('ui-company-footer');footer.replaceChildren();
  const identity=el('div'),support=companyIdentity.support;
  identity.append(el('span','',`© ${companyIdentity.name}`));
  const parts=[support.department,support.extension?`내선 ${support.extension}`:'',support.hours].filter(Boolean);
  if(parts.length)identity.append(el('p','ui-company-footer-contact',parts.join(' · ')+(support.isExample?' (예시)':'')));
  const actions=el('div','ui-company-footer-actions');
  for(const [key,label,callback] of [['guide','이용 안내',onGuide],['contact','문의',onContact]]){
   const url=companyIdentity.links[key];
   if(!url&&!callback)continue;
   const action=el(url?'a':'button','',label);
   if(url)action.href=url;else{action.type='button';action.dataset.uiIcon='none';action.addEventListener('click',callback);cleanups.push(()=>action.removeEventListener('click',callback));}
   actions.append(action);
  }
  footer.append(identity,actions);
 }
 return {destroy(){for(const cleanup of cleanups)cleanup();}};
}
